int intersections = 0;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(0.0, 1.0);

// Get the bounding box of the mesh from the tree
const cg3::BoundingBox3& meshBB = tree.bb;
double bbDiag = meshBB.diag();
cg3::Point3d farPoint = p;

// Cast multiple rays in random directions
for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction
    double theta = dis(gen) * 2.0 * M_PI;
    double phi = std::acos(dis(gen) * 2.0 - 1.0);
    double x = std::sin(phi) * std::cos(theta);
    double y = std::sin(phi) * std::sin(theta);
    double z = std::cos(phi);
    cg3::Point3d direction(x, y, z);
    direction.normalize();

    // Create a far point in the direction
    farPoint = p + direction * (bbDiag * 2); // Ensure it's far outside the bounding box

    // Count intersections using the existing method
    int n = tree.numberIntersectedPrimitives(p, farPoint);
    if (n % 2 == 1) {
        intersections++;
    }
}

// If majority of rays intersect an odd number of times, point is inside
return intersections > numberOfChecks / 2;

